+++ b/lib/auth/touchid/diag.m
@@ -0,0 +1,44 @@
+//go:build touchid
+// +build touchid
+
+#include "diag.h"
+
+#import <Foundation/Foundation.h>
+#import <LocalAuthentication/LocalAuthentication.h>
+#import <Security/Security.h>
+#import <Security/SecCode.h>
+
+void TouchIDDiag(bool *signature, bool *entitlements, bool *laPolicy,
+                 bool *secureEnclave) {
+  SecCodeRef code = NULL;
+  if (SecCodeCopySelf(kSecCSDefaultFlags, &code) == errSecSuccess) {
+    *signature = SecCodeCheckValidity(code, kSecCSDefaultFlags, NULL) == errSecSuccess;
+
+    CFDictionaryRef signingInfo = NULL;
+    if (SecCodeCopySigningInformation(code, kSecCSSigningInformation,
+                                      &signingInfo) == errSecSuccess) {
+      CFDictionaryRef values =
+          CFDictionaryGetValue(signingInfo, kSecCodeInfoEntitlementsDict);
+      *entitlements = values &&
+          CFDictionaryGetValue(values, CFSTR("keychain-access-groups")) != NULL;
+      CFRelease(signingInfo);
+    }
+    CFRelease(code);
+  }
+
+  LAContext *context = [[LAContext alloc] init];
+  *laPolicy = [context canEvaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics
+                                   error:NULL];
+
+  NSDictionary *attributes = @{
+    (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
+    (id)kSecAttrKeySizeInBits : @256,
+    (id)kSecAttrTokenID : (id)kSecAttrTokenIDSecureEnclave,
+    (id)kSecPrivateKeyAttrs : @{(id)kSecAttrIsPermanent : @NO},
+  };
+  SecKeyRef key = SecKeyCreateRandomKey((__bridge CFDictionaryRef)attributes, NULL);
+  *secureEnclave = key != NULL;
+  if (key) {
+    CFRelease(key);
+  }
+}
