+	var signature, entitlements, laPolicy, secureEnclave C.bool
+	C.TouchIDDiag(&signature, &entitlements, &laPolicy, &secureEnclave)
+	result := &DiagResult{
+		HasCompileSupport:       true,
+		HasSignature:            bool(signature),
+		HasEntitlements:         bool(entitlements),
+		PassedLAPolicyTest:      bool(laPolicy),
+		PassedSecureEnclaveTest: bool(secureEnclave),
+	}
+	result.IsAvailable = result.HasCompileSupport && result.HasSignature && result.HasEntitlements &&
+		result.PassedLAPolicyTest && result.PassedSecureEnclaveTest
+	return result, nil
+}
